		int y = py;
		s = 0; // Initialize.
		for (i = n - 1; i >= 0; i--) {
			xi = (x >> i) & 1; // Get bit i of x.
			yi = (y >> i) & 1; // Get bit i of y.

			if (yi == 0) {
				temp = x; // Swap x and y and,
				x = y ^ (-xi); // if xi = 1,
				y = temp ^ (-xi); // complement them.
			}
			s = 4 * s + 2 * xi + (xi ^ yi); // Append two bits to s.
		}
		return s;
	}

