		int s, temp;

		int x = px;
		int y = py;
		s = 0; // Initialize.
		for (i = n - 1; i >= 0; i--) {
			xi = (x >> i) & 1; // Get bit i of x.
			yi = (y >> i) & 1; // Get bit i of y.

			if (yi == 0) {
