		final List<PVector> points = new ArrayList<>(n);
		for (int i = 0; i < n; i++) {
			float x = offset + (rookPositions.get(i) / (float) n);
			x *= w;
			x += xMin;
			float y = offset + i / (float) n;
			y *= h;
			y += yMin;
			points.add(new PVector(x, y));
		}

