			{
				this.put(BlockChainFeature.PROOF_OF_IMPORTANCE,
						() -> new PoiImportanceCalculator(new PoiScorer(), NisAppConfig::getBlockDependentPoiOptions));
				this.put(BlockChainFeature.PROOF_OF_STAKE, PosImportanceCalculator::new);
			}
