        engine.persist("TEST", entry().set("COL1", 4).set("COL2", "teste").set("COL3", "teste").build());
        engine.persist(
                "TEST",
                entry().set("COL1", 5).set("COL2", "pomme de terre").set("COL3", "pomme de terre").build()
        );
        engine.persist(
